data: {"level":2,"reviewed":{"level":2,"label":"formula / approach","text":"Let $\\log p_j = z_j - \\mathrm{LSE}(z)$, where $\\mathrm{LSE}$ is log-sum-exp and $z$ are the logits,\nand do the same for q. Then $\\mathrm{KL} = \\sum_j p_j(\\log p_j - \\log q_j)$. Two cases are\nspecial: $p_j = 0$ contributes $0$, and $q_j = 0$ with $p_j > 0$ gives $+\\infty$."},"hints_note":null}

